 SELECT CASE WHEN EXISTS(SELECT 1 FROM astra_tarot25_offers29 WHERE offer_id=NEW.offer_id)THEN RAISE(IGNORE)END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM astra_tarot31_intents i JOIN astra_tarot31_policy p ON p.singleton=1 JOIN astra_tarot30_policy s ON s.singleton=1 WHERE i.offer_id=NEW.offer_id AND i.telegram_id=NEW.telegram_id AND i.generation=NEW.generation AND i.request_key=NEW.request_key AND i.update_id=NEW.update_id AND i.spread_id=NEW.spread_id AND i.theme=NEW.theme AND i.price=NEW.price AND i.policy_revision=NEW.policy_revision AND i.state=''sealing'' AND i.lease_until>unixepoch() AND i.expires_at>unixepoch() AND p.enabled=1 AND p.revision=i.intent_revision AND s.write_enabled=1 AND json_extract(NEW.snapshot_json,''$.created_at'')=strftime(''%Y-%m-%dT%H:%M:%fZ'',i.created_at,''unixepoch'') AND json_extract(NEW.snapshot_json,''$.question'') IS(SELECT text FROM astra_tarot31_questions WHERE offer_id=i.offer_id))THEN RAISE(ABORT,''INTENT_SEAL_AUTHORITY'')END;
 SELECT CASE WHEN json_type(NEW.snapshot_json,''$.question'')=''text'' AND NOT EXISTS(SELECT 1 FROM astra_tarot31_questions q WHERE q.offer_id=NEW.offer_id AND q.text=json_extract(NEW.snapshot_json,''$.question'') AND q.policy_version=json_extract(NEW.snapshot_json,''$.question_proof.policy_version'') AND q.consented_at=json_extract(NEW.snapshot_json,''$.question_proof.consented_at'') AND q.consent_update=json_extract(NEW.snapshot_json,''$.question_proof.consent_update'') AND q.consent_message=json_extract(NEW.snapshot_json,''$.question_proof.consent_message''))THEN RAISE(ABORT,''QUESTION_PROOF_MISMATCH'')END;
 SELECT CASE WHEN NEW.engine_version<>''tarot25-v2'' OR json_extract(NEW.snapshot_json,''$.text_version'') IS NOT ''rws78-interpretation-v2'' THEN RAISE(ABORT,''INTENT_TEXT_VERSION'')END;
 SELECT CASE WHEN(SELECT page_count FROM pragma_page_count)*(SELECT page_size FROM pragma_page_size)+2*(length(CAST(NEW.snapshot_json AS BLOB))+length(CAST(NEW.result AS BLOB)))+65536>(SELECT soft_cap_bytes FROM astra_tarot30_policy)THEN RAISE(ABORT,''DRAFT_STORAGE_SOFT_CAP'')END;
END'),('astra_tarot30_offer_erased','trigger','CREATE TRIGGER astra_tarot30_offer_erased AFTER DELETE ON astra_tarot25_offers29 WHEN EXISTS(SELECT 1 FROM astra_users WHERE telegram_id=OLD.telegram_id) BEGIN
 UPDATE astra_tarot30_cleanup_runs SET deleted_count=deleted_count+1,payload_bytes=payload_bytes+length(CAST(OLD.snapshot_json AS BLOB))+length(CAST(OLD.result AS BLOB)) WHERE token=(SELECT token FROM astra_tarot30_cleanup_claims WHERE offer_id=OLD.offer_id);
 DELETE FROM astra_tarot30_cleanup_claims WHERE offer_id=OLD.offer_id;
END'),('astra_tarot30_offer_post','trigger','CREATE TRIGGER astra_tarot30_offer_post AFTER INSERT ON astra_tarot25_offers29 BEGIN
 INSERT INTO astra_tarot30_requests VALUES(NEW.telegram_id,NEW.generation,NEW.request_key,NEW.update_id,NEW.offer_id,NEW.spread_id,NEW.theme,NEW.created_at,1);
 UPDATE astra_tarot31_intents SET state=''sealed'',lease=NULL,lease_until=0 WHERE offer_id=NEW.offer_id;
END'),('astra_tarot30_policy','table','CREATE TABLE astra_tarot30_policy(
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),version TEXT NOT NULL DEFAULT ''tarot30-local-proposal-v1'' CHECK(version=''tarot30-local-proposal-v1''),
 migration_done INTEGER NOT NULL DEFAULT 0 CHECK(migration_done IN(0,1)),write_enabled INTEGER NOT NULL DEFAULT 0 CHECK(write_enabled IN(0,1)),cleanup_enabled INTEGER NOT NULL DEFAULT 0 CHECK(cleanup_enabled IN(0,1)),
 retention_seconds INTEGER NOT NULL DEFAULT 86400 CHECK(typeof(retention_seconds)=''integer'' AND retention_seconds BETWEEN 3600 AND 2592000),daily_limit INTEGER NOT NULL DEFAULT 3 CHECK(typeof(daily_limit)=''integer'' AND daily_limit BETWEEN 1 AND 10000),
 batch_limit INTEGER NOT NULL DEFAULT 20 CHECK(typeof(batch_limit)=''integer'' AND batch_limit BETWEEN 1 AND 20),soft_cap_bytes INTEGER NOT NULL DEFAULT 350000000 CHECK(typeof(soft_cap_bytes)=''integer'' AND soft_cap_bytes BETWEEN 1048576 AND 450000000),revision INTEGER NOT NULL DEFAULT 0 CHECK(typeof(revision)=''integer'' AND revision>=0)
)'),('astra_tarot30_policy_delete','trigger','CREATE TRIGGER astra_tarot30_policy_delete BEFORE DELETE ON astra_tarot30_policy BEGIN SELECT RAISE(ABORT,''Retention policy required'');END'),('astra_tarot30_policy_insert','trigger','CREATE TRIGGER astra_tarot30_policy_insert BEFORE INSERT ON astra_tarot30_policy WHEN EXISTS(SELECT 1 FROM astra_tarot30_policy WHERE singleton=NEW.singleton) BEGIN SELECT RAISE(IGNORE);END'),('astra_tarot30_policy_update','trigger','CREATE TRIGGER astra_tarot30_policy_update BEFORE UPDATE ON astra_tarot30_policy BEGIN
 SELECT CASE WHEN NEW.singleton<>OLD.singleton OR NEW.version<>OLD.version OR (OLD.migration_done=1 AND NEW.migration_done<>1) OR NEW.revision<OLD.revision OR ((NEW.write_enabled=1 OR NEW.cleanup_enabled=1) AND NEW.migration_done<>1) THEN RAISE(ABORT,''Invalid retention policy transition'') END;
 SELECT CASE WHEN (NEW.retention_seconds<>OLD.retention_seconds OR NEW.daily_limit<>OLD.daily_limit OR NEW.batch_limit<>OLD.batch_limit OR NEW.soft_cap_bytes<>OLD.soft_cap_bytes) AND (OLD.write_enabled=1 OR OLD.cleanup_enabled=1 OR NEW.write_enabled=1 OR NEW.cleanup_enabled=1 OR NEW.revision<>OLD.revision+1) THEN RAISE(ABORT,''Close storage gates and revise policy before changes'') END;
END'),('astra_tarot30_quota','table','CREATE TABLE astra_tarot30_quota(day TEXT NOT NULL,subject TEXT NOT NULL,used INTEGER NOT NULL CHECK(typeof(used)=''integer'' AND used>=0),PRIMARY KEY(day,subject))'),('astra_tarot30_quota_delete','trigger','CREATE TRIGGER astra_tarot30_quota_delete BEFORE DELETE ON astra_tarot30_quota BEGIN
 SELECT CASE WHEN OLD.day>=date(unixepoch(),''unixepoch'',''+3 hours'') OR NOT EXISTS(SELECT 1 FROM astra_tarot30_cleanup_runs r JOIN astra_tarot30_policy s ON s.singleton=1 WHERE r.finished_at=0 AND r.started_at=unixepoch() AND r.revision=s.revision AND s.cleanup_enabled=1 AND r.deleted_count+r.quota_deleted<r.batch_limit) THEN RAISE(ABORT,''Draft quota cleanup not authorized'') END;
END'),('astra_tarot30_quota_erased','trigger','CREATE TRIGGER astra_tarot30_quota_erased AFTER DELETE ON astra_tarot30_quota BEGIN
