END'),('astra_tarot31_burst','table','CREATE TABLE astra_tarot31_burst(telegram_id INTEGER NOT NULL REFERENCES astra_users(telegram_id)ON DELETE CASCADE,generation TEXT NOT NULL,window INTEGER NOT NULL,used INTEGER NOT NULL CHECK(typeof(used)=''integer'' AND used>=0),PRIMARY KEY(telegram_id,generation,window))'),('astra_tarot31_burst_delete','trigger','CREATE TRIGGER astra_tarot31_burst_delete BEFORE DELETE ON astra_tarot31_burst WHEN EXISTS(SELECT 1 FROM astra_users WHERE telegram_id=OLD.telegram_id)BEGIN
