END'),('astra_tarot31_burst_erased','trigger','CREATE TRIGGER astra_tarot31_burst_erased AFTER DELETE ON astra_tarot31_burst WHEN EXISTS(SELECT 1 FROM astra_users WHERE telegram_id=OLD.telegram_id)BEGIN UPDATE astra_tarot31_gc SET deleted=deleted+1 WHERE finished_at=0 AND started_at=unixepoch();END'),('astra_tarot31_burst_insert','trigger','CREATE TRIGGER astra_tarot31_burst_insert BEFORE INSERT ON astra_tarot31_burst BEGIN
 SELECT CASE WHEN NEW.window<>unixepoch()/60 OR NEW.used<>1 OR NOT EXISTS(SELECT 1 FROM astra_tarot31_intents i JOIN astra_user_policy g USING(telegram_id) WHERE i.telegram_id=NEW.telegram_id AND i.generation=NEW.generation AND g.generation=i.generation AND i.created_at=unixepoch())THEN RAISE(ABORT,''BURST_AUTHORITY'')END;
END'),('astra_tarot31_burst_update','trigger','CREATE TRIGGER astra_tarot31_burst_update BEFORE UPDATE ON astra_tarot31_burst BEGIN
 SELECT CASE WHEN NEW.telegram_id<>OLD.telegram_id OR NEW.generation<>OLD.generation OR NEW.window<>OLD.window OR NOT(NEW.used=OLD.used+1 AND NEW.window=unixepoch()/60 OR NEW.used=max(OLD.used-1,0) AND EXISTS(SELECT 1 FROM astra_tarot25_purchases29 p JOIN astra_tarot31_intents i USING(offer_id) WHERE p.telegram_id=OLD.telegram_id AND p.generation=OLD.generation AND i.created_at/60=OLD.window AND p.created_at=unixepoch()))THEN RAISE(ABORT,''BURST_TRANSITION'')END;
END'),('astra_tarot31_complete','trigger','CREATE TRIGGER astra_tarot31_complete BEFORE UPDATE OF migration_done ON astra_tarot31_policy WHEN NEW.migration_done=1 BEGIN SELECT CASE WHEN NEW.enabled+NEW.questions_enabled+NEW.cleanup_enabled<>0 OR(SELECT count(*) FROM sqlite_master WHERE name IN(''astra_tarot31_complete_0'',''astra_tarot31_complete_1'',''astra_tarot31_complete_2'',''astra_tarot31_complete_3'',''astra_tarot31_complete_4'',''astra_tarot31_complete_5'',''astra_tarot31_complete_6'',''astra_tarot31_complete_7'',''astra_tarot31_complete_8'',''astra_tarot31_complete_9'',''astra_tarot31_complete_10'',''astra_tarot31_complete_11'',''astra_tarot31_complete_12'',''astra_tarot31_complete_13'',''astra_tarot31_complete_14'',''astra_tarot31_complete_15'',''astra_tarot31_complete_16'',''astra_tarot31_complete_17'',''astra_tarot31_complete_18'',''astra_tarot31_complete_19'',''astra_tarot31_complete_20''))<>21 THEN RAISE(ABORT,''Tarot31 completion gates'')END;END')) SELECT 1 FROM expected e LEFT JOIN sqlite_master a ON a.name=e.name WHERE a.type IS NOT e.type OR trim(a.sql) IS NOT trim(e.definition))THEN '{"ok":1}' ELSE 'ASTRA251_BASE_SCHEMA_MISMATCH' END,'$.ok');
