 DELETE FROM astra_tarot31_burst WHERE(telegram_id,generation,window)IN(SELECT telegram_id,generation,window FROM astra_tarot31_burst WHERE window<unixepoch()/60-10 ORDER BY window LIMIT(SELECT limit_rows-deleted FROM astra_tarot31_gc WHERE token=NEW.token));
 UPDATE astra_tarot31_gc SET finished_at=unixepoch()WHERE token=NEW.token;
END'),('astra_tarot31_gc_insert','trigger','CREATE TRIGGER astra_tarot31_gc_insert BEFORE INSERT ON astra_tarot31_gc BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM astra_tarot31_gc WHERE token=NEW.token AND(limit_rows<>NEW.limit_rows OR revision<>NEW.revision OR retention_seconds<>NEW.retention_seconds))THEN RAISE(ABORT,''GC_TOKEN_MISMATCH'')END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM astra_tarot31_gc WHERE token=NEW.token)THEN RAISE(IGNORE)END;
 SELECT CASE WHEN NEW.started_at<>unixepoch() OR NEW.finished_at<>0 OR NEW.deleted<>0 OR NOT EXISTS(SELECT 1 FROM astra_tarot31_policy p JOIN astra_tarot30_policy s ON s.singleton=1 WHERE p.singleton=1 AND p.migration_done=1 AND p.cleanup_enabled=1 AND s.cleanup_enabled=1 AND NEW.revision=p.revision AND NEW.retention_seconds=s.retention_seconds AND NEW.limit_rows<=s.batch_limit)THEN RAISE(ABORT,''INTENT_GC_DISABLED'')END;
END'),('astra_tarot31_gc_update','trigger','CREATE TRIGGER astra_tarot31_gc_update BEFORE UPDATE ON astra_tarot31_gc BEGIN
 SELECT CASE WHEN OLD.finished_at<>0 OR NEW.token<>OLD.token OR NEW.limit_rows<>OLD.limit_rows OR NEW.revision<>OLD.revision OR NEW.retention_seconds<>OLD.retention_seconds OR NEW.started_at<>OLD.started_at OR NEW.deleted<OLD.deleted OR NEW.deleted>NEW.limit_rows OR(NEW.finished_at<>0 AND NEW.finished_at<>unixepoch())THEN RAISE(ABORT,''GC immutable'')END;
END'),('astra_tarot31_intent_delete','trigger','CREATE TRIGGER astra_tarot31_intent_delete BEFORE DELETE ON astra_tarot31_intents WHEN EXISTS(SELECT 1 FROM astra_users WHERE telegram_id=OLD.telegram_id)BEGIN
 SELECT CASE WHEN OLD.state=''paid'' OR EXISTS(SELECT 1 FROM astra_tarot25_offers29 WHERE offer_id=OLD.offer_id) OR EXISTS(SELECT 1 FROM astra_tarot25_purchases29 WHERE offer_id=OLD.offer_id) OR OLD.expires_at+(SELECT retention_seconds FROM astra_tarot30_policy)>unixepoch() OR NOT EXISTS(SELECT 1 FROM astra_tarot31_gc r JOIN astra_tarot31_policy p ON p.singleton=1 WHERE r.finished_at=0 AND r.started_at=unixepoch() AND r.deleted<r.limit_rows AND p.cleanup_enabled=1)THEN RAISE(ABORT,''INTENT_DELETE_AUTHORITY'')END;
END'),('astra_tarot31_intent_erased','trigger','CREATE TRIGGER astra_tarot31_intent_erased AFTER DELETE ON astra_tarot31_intents BEGIN
 DELETE FROM astra_tarot31_questions WHERE offer_id=OLD.offer_id;
 UPDATE astra_tarot31_gc SET deleted=deleted+1 WHERE finished_at=0 AND started_at=unixepoch() AND EXISTS(SELECT 1 FROM astra_users WHERE telegram_id=OLD.telegram_id);
END'),('astra_tarot31_intent_insert','trigger','CREATE TRIGGER astra_tarot31_intent_insert BEFORE INSERT ON astra_tarot31_intents BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM astra_tarot31_receipts WHERE telegram_id=NEW.telegram_id AND generation=NEW.generation AND(request_key=NEW.request_key OR update_id=NEW.update_id))THEN RAISE(ABORT,''INTENT_REQUEST_SEEN'') END;
 SELECT CASE WHEN NEW.state<>''quoted'' OR NEW.lease IS NOT NULL OR NEW.lease_until<>0 OR NEW.created_at<>unixepoch() OR NOT EXISTS(SELECT 1 FROM astra_users u JOIN astra_user_policy g USING(telegram_id) JOIN astra_tarot25_runtime29 r ON r.singleton=1 JOIN astra_tarot30_policy s ON s.singleton=1 JOIN astra_tarot31_policy p ON p.singleton=1 JOIN astra_tarot25_prices29 t ON t.price_version=r.price_version AND t.spread_id=NEW.spread_id WHERE u.telegram_id=NEW.telegram_id AND g.generation=NEW.generation AND r.enabled=1 AND r.migration_done=1 AND s.migration_done=1 AND s.write_enabled=1 AND p.migration_done=1 AND p.enabled=1 AND p.revision=NEW.intent_revision AND r.revision=NEW.policy_revision AND NEW.price_version=t.price_version AND NEW.price=t.price AND(t.theme=''general'' OR t.theme=NEW.theme))THEN RAISE(ABORT,''INTENT_GATE_OR_OWNER'')END;
 SELECT CASE WHEN(SELECT count(*) FROM astra_tarot31_intents WHERE telegram_id=NEW.telegram_id AND generation=NEW.generation AND state IN(''quoted'',''sealing'',''sealed'') AND expires_at>unixepoch())>=(SELECT max_open FROM astra_tarot31_policy)THEN RAISE(ABORT,''INTENT_OPEN_LIMIT'')END;
 SELECT CASE WHEN coalesce((SELECT used FROM astra_tarot31_burst WHERE telegram_id=NEW.telegram_id AND generation=NEW.generation AND window=unixepoch()/60),0)>=(SELECT burst_limit FROM astra_tarot31_policy)THEN RAISE(ABORT,''INTENT_BURST_LIMIT'')END;
 SELECT CASE WHEN(SELECT page_count FROM pragma_page_count)*(SELECT page_size FROM pragma_page_size)+65536>(SELECT soft_cap_bytes FROM astra_tarot30_policy)THEN RAISE(ABORT,''DRAFT_STORAGE_SOFT_CAP'')END;
END'),('astra_tarot31_intent_post','trigger','CREATE TRIGGER astra_tarot31_intent_post AFTER INSERT ON astra_tarot31_intents BEGIN
 INSERT INTO astra_tarot31_receipts VALUES(NEW.telegram_id,NEW.generation,NEW.request_key,NEW.update_id,NEW.offer_id,NEW.spread_id,NEW.theme);
 INSERT INTO astra_tarot31_burst VALUES(NEW.telegram_id,NEW.generation,unixepoch()/60,1)ON CONFLICT(telegram_id,generation,window)DO UPDATE SET used=used+1;
END'),('astra_tarot31_intent_update','trigger','CREATE TRIGGER astra_tarot31_intent_update BEFORE UPDATE ON astra_tarot31_intents BEGIN
 SELECT CASE WHEN NEW.offer_id IS NOT OLD.offer_id OR NEW.telegram_id IS NOT OLD.telegram_id OR NEW.generation IS NOT OLD.generation OR NEW.request_key IS NOT OLD.request_key OR NEW.update_id IS NOT OLD.update_id OR NEW.spread_id IS NOT OLD.spread_id OR NEW.theme IS NOT OLD.theme OR NEW.price IS NOT OLD.price OR NEW.price_version IS NOT OLD.price_version OR NEW.policy_revision IS NOT OLD.policy_revision OR NEW.intent_revision IS NOT OLD.intent_revision OR NEW.seed IS NOT OLD.seed OR NEW.created_at IS NOT OLD.created_at OR NEW.expires_at IS NOT OLD.expires_at THEN RAISE(ABORT,''Intent identity immutable'')END;
 SELECT CASE WHEN NOT((OLD.state=''quoted'' OR(OLD.state=''sealing'' AND OLD.lease_until<=unixepoch()))AND NEW.state=''sealing'' AND NEW.lease IS NOT NULL AND NEW.lease IS NOT OLD.lease AND NEW.lease_until=unixepoch()+30 AND OLD.expires_at>unixepoch() AND EXISTS(SELECT 1 FROM astra_users u JOIN astra_user_policy g USING(telegram_id) JOIN astra_tarot25_runtime29 r ON r.singleton=1 JOIN astra_tarot30_policy s ON s.singleton=1 JOIN astra_tarot31_policy p ON p.singleton=1 WHERE u.telegram_id=OLD.telegram_id AND g.generation=OLD.generation AND u.balance>=OLD.price AND r.enabled=1 AND r.revision=OLD.policy_revision AND s.write_enabled=1 AND p.enabled=1 AND p.revision=OLD.intent_revision) AND NOT EXISTS(SELECT 1 FROM astra_tarot31_questions WHERE offer_id=OLD.offer_id AND text IS NULL)
 OR OLD.state=''sealing'' AND NEW.state=''sealed'' AND NEW.lease IS NULL AND NEW.lease_until=0 AND EXISTS(SELECT 1 FROM astra_tarot25_offers29 WHERE offer_id=OLD.offer_id)
 OR OLD.state=''sealed'' AND NEW.state=''paid'' AND NEW.lease IS NULL AND NEW.lease_until=0 AND EXISTS(SELECT 1 FROM astra_tarot25_purchases29 WHERE offer_id=OLD.offer_id)
 OR OLD.state IN(''quoted'',''sealed'') AND NEW.state=''cancelled'' AND NEW.lease IS NULL AND NEW.lease_until=0 AND NOT EXISTS(SELECT 1 FROM astra_tarot25_purchases29 WHERE offer_id=OLD.offer_id))THEN RAISE(ABORT,''INTENT_STATE_OR_FUNDS'')END;
END'),('astra_tarot31_intents','table','CREATE TABLE astra_tarot31_intents(offer_id TEXT PRIMARY KEY NOT NULL CHECK(length(offer_id)=32 AND offer_id NOT GLOB ''*[^a-f0-9]*''),telegram_id INTEGER NOT NULL REFERENCES astra_users(telegram_id)ON DELETE CASCADE,generation TEXT NOT NULL,request_key TEXT NOT NULL CHECK(length(request_key)BETWEEN 1 AND 128),update_id INTEGER NOT NULL CHECK(typeof(update_id)=''integer'' AND update_id>=0),spread_id TEXT NOT NULL,theme TEXT NOT NULL CHECK(theme IN(''general'',''relations'',''work'',''choice'',''resources'')),price INTEGER NOT NULL,price_version TEXT NOT NULL,policy_revision INTEGER NOT NULL,intent_revision INTEGER NOT NULL,seed TEXT NOT NULL CHECK(length(seed)=64 AND seed NOT GLOB ''*[^a-f0-9]*''),state TEXT NOT NULL DEFAULT ''quoted'' CHECK(state IN(''quoted'',''sealing'',''sealed'',''paid'',''cancelled'')),lease TEXT,lease_until INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL DEFAULT(unixepoch()),expires_at INTEGER NOT NULL CHECK(expires_at=created_at+900),UNIQUE(telegram_id,generation,request_key),UNIQUE(telegram_id,generation,update_id))'),('astra_tarot31_policy','table','CREATE TABLE astra_tarot31_policy(singleton INTEGER PRIMARY KEY CHECK(singleton=1),version TEXT NOT NULL DEFAULT ''tarot31-v1'' CHECK(version=''tarot31-v1''),migration_done INTEGER NOT NULL DEFAULT 0 CHECK(migration_done IN(0,1)),enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)),questions_enabled INTEGER NOT NULL DEFAULT 0 CHECK(questions_enabled IN(0,1)),cleanup_enabled INTEGER NOT NULL DEFAULT 0 CHECK(cleanup_enabled IN(0,1)),max_open INTEGER NOT NULL DEFAULT 5 CHECK(typeof(max_open)=''integer'' AND max_open BETWEEN 1 AND 20),burst_limit INTEGER NOT NULL DEFAULT 20 CHECK(typeof(burst_limit)=''integer'' AND burst_limit BETWEEN 4 AND 100),revision INTEGER NOT NULL DEFAULT 0 CHECK(typeof(revision)=''integer'' AND revision>=0))'),('astra_tarot31_policy_delete','trigger','CREATE TRIGGER astra_tarot31_policy_delete BEFORE DELETE ON astra_tarot31_policy BEGIN SELECT RAISE(ABORT,''Policy31 required'');END'),('astra_tarot31_policy_insert','trigger','CREATE TRIGGER astra_tarot31_policy_insert BEFORE INSERT ON astra_tarot31_policy WHEN EXISTS(SELECT 1 FROM astra_tarot31_policy)BEGIN SELECT RAISE(IGNORE);END'),('astra_tarot31_policy_update','trigger','CREATE TRIGGER astra_tarot31_policy_update BEFORE UPDATE ON astra_tarot31_policy BEGIN
 SELECT CASE WHEN NEW.singleton<>OLD.singleton OR NEW.version<>OLD.version OR NEW.revision<OLD.revision OR(OLD.migration_done=1 AND NEW.migration_done<>1) OR((NEW.enabled OR NEW.questions_enabled OR NEW.cleanup_enabled)AND NEW.migration_done<>1) THEN RAISE(ABORT,''Policy31 transition'') END;
 SELECT CASE WHEN(NEW.max_open<>OLD.max_open OR NEW.burst_limit<>OLD.burst_limit)AND(NEW.enabled OR OLD.enabled OR NEW.cleanup_enabled OR OLD.cleanup_enabled OR NEW.questions_enabled OR OLD.questions_enabled OR NEW.revision<>OLD.revision+1)THEN RAISE(ABORT,''Policy31 close gates and revise'') END;
END'),('astra_tarot31_purchase_guard','trigger','CREATE TRIGGER astra_tarot31_purchase_guard BEFORE INSERT ON astra_tarot25_purchases29 WHEN EXISTS(SELECT 1 FROM astra_tarot31_receipts WHERE offer_id=NEW.offer_id)AND NOT EXISTS(SELECT 1 FROM astra_tarot25_purchases29 WHERE offer_id=NEW.offer_id)BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM astra_tarot31_intents i JOIN astra_tarot31_policy p ON p.singleton=1 JOIN astra_tarot30_policy s ON s.singleton=1 WHERE i.offer_id=NEW.offer_id AND i.state=''sealed'' AND i.expires_at>unixepoch() AND p.enabled=1 AND p.revision=i.intent_revision AND s.write_enabled=1)THEN RAISE(ABORT,''INTENT_PAYMENT_GATE'')END;
END'),('astra_tarot31_purchase_post','trigger','CREATE TRIGGER astra_tarot31_purchase_post AFTER INSERT ON astra_tarot25_purchases29 WHEN EXISTS(SELECT 1 FROM astra_tarot31_intents WHERE offer_id=NEW.offer_id)BEGIN
 UPDATE astra_tarot31_intents SET state=''paid'',lease=NULL,lease_until=0 WHERE offer_id=NEW.offer_id;
 UPDATE astra_tarot31_burst SET used=max(used-1,0)WHERE telegram_id=NEW.telegram_id AND generation=NEW.generation AND window=(SELECT created_at/60 FROM astra_tarot31_intents WHERE offer_id=NEW.offer_id);
 DELETE FROM astra_tarot31_questions WHERE offer_id=NEW.offer_id;
END'),('astra_tarot31_question_delete','trigger','CREATE TRIGGER astra_tarot31_question_delete BEFORE DELETE ON astra_tarot31_questions WHEN EXISTS(SELECT 1 FROM astra_tarot31_intents i JOIN astra_users u USING(telegram_id) WHERE i.offer_id=OLD.offer_id AND i.state IN(''sealing'',''sealed''))BEGIN SELECT RAISE(ABORT,''Question sealed'');END'),('astra_tarot31_question_insert','trigger','CREATE TRIGGER astra_tarot31_question_insert BEFORE INSERT ON astra_tarot31_questions BEGIN
 SELECT CASE WHEN NEW.consented_at<>unixepoch() OR NEW.text IS NOT NULL OR NEW.text_update IS NOT NULL OR NOT EXISTS(SELECT 1 FROM astra_tarot31_intents i JOIN astra_user_policy g USING(telegram_id) JOIN astra_tarot31_policy p ON p.singleton=1 JOIN astra_tarot25_runtime29 r ON r.singleton=1 JOIN astra_tarot30_policy s ON s.singleton=1 WHERE r.enabled=1 AND s.write_enabled=1 AND i.offer_id=NEW.offer_id AND g.generation=i.generation AND i.state=''quoted'' AND i.expires_at>unixepoch() AND p.enabled=1 AND p.questions_enabled=1) OR EXISTS(SELECT 1 FROM astra_tarot31_questions q JOIN astra_tarot31_intents x ON x.offer_id=q.offer_id JOIN astra_tarot31_intents i ON i.offer_id=NEW.offer_id WHERE x.telegram_id=i.telegram_id AND x.generation=i.generation AND x.state=''quoted'' AND x.expires_at>unixepoch() AND q.text IS NULL AND x.offer_id<>i.offer_id)THEN RAISE(ABORT,''QUESTION_CONSENT_AUTHORITY'')END;
END'),('astra_tarot31_question_update','trigger','CREATE TRIGGER astra_tarot31_question_update BEFORE UPDATE ON astra_tarot31_questions BEGIN
 SELECT CASE WHEN NEW.offer_id<>OLD.offer_id OR NEW.policy_version<>OLD.policy_version OR NEW.consented_at<>OLD.consented_at OR NEW.consent_update<>OLD.consent_update OR NEW.consent_message<>OLD.consent_message OR OLD.text IS NOT NULL OR NEW.text IS NULL OR NEW.text_update IS NULL OR NOT EXISTS(SELECT 1 FROM astra_tarot31_intents i JOIN astra_user_policy g USING(telegram_id) JOIN astra_tarot31_policy p ON p.singleton=1 JOIN astra_tarot25_runtime29 r ON r.singleton=1 JOIN astra_tarot30_policy s ON s.singleton=1 WHERE r.enabled=1 AND s.write_enabled=1 AND i.offer_id=NEW.offer_id AND i.generation=g.generation AND i.state=''quoted'' AND i.expires_at>unixepoch() AND p.enabled=1 AND p.questions_enabled=1)THEN RAISE(ABORT,''QUESTION_IMMUTABLE_OR_EXPIRED'')END;
END'),('astra_tarot31_questions','table','CREATE TABLE astra_tarot31_questions(offer_id TEXT PRIMARY KEY NOT NULL REFERENCES astra_tarot31_intents(offer_id)ON DELETE CASCADE,policy_version TEXT NOT NULL CHECK(policy_version=''tarot-question-consent-v1''),consented_at INTEGER NOT NULL DEFAULT(unixepoch()),consent_update INTEGER NOT NULL CHECK(typeof(consent_update)=''integer'' AND consent_update>=0),consent_message INTEGER NOT NULL CHECK(typeof(consent_message)=''integer'' AND consent_message>0),text TEXT CHECK(text IS NULL OR(length(text)BETWEEN 1 AND 500 AND length(CAST(text AS BLOB))<=2000)),text_update INTEGER CHECK(text_update IS NULL OR(typeof(text_update)=''integer'' AND text_update>consent_update)))'),('astra_tarot31_receipt_delete','trigger','CREATE TRIGGER astra_tarot31_receipt_delete BEFORE DELETE ON astra_tarot31_receipts WHEN EXISTS(SELECT 1 FROM astra_users WHERE telegram_id=OLD.telegram_id)BEGIN SELECT RAISE(ABORT,''Erase receipt with profile'');END'),('astra_tarot31_receipt_insert','trigger','CREATE TRIGGER astra_tarot31_receipt_insert BEFORE INSERT ON astra_tarot31_receipts BEGIN
