END'),('astra_tarot31_receipt_update','trigger','CREATE TRIGGER astra_tarot31_receipt_update BEFORE UPDATE ON astra_tarot31_receipts BEGIN SELECT RAISE(ABORT,''Intent receipt immutable'');END'),('astra_tarot31_receipts','table','CREATE TABLE astra_tarot31_receipts(telegram_id INTEGER NOT NULL REFERENCES astra_users(telegram_id)ON DELETE CASCADE,generation TEXT NOT NULL,request_key TEXT NOT NULL,update_id INTEGER NOT NULL,offer_id TEXT NOT NULL UNIQUE,spread_id TEXT NOT NULL,theme TEXT NOT NULL,PRIMARY KEY(telegram_id,generation,request_key),UNIQUE(telegram_id,generation,update_id))'),('astra_tarot_erase26','trigger','CREATE TRIGGER astra_tarot_erase26 AFTER DELETE ON astra_users BEGIN
