 price INTEGER NOT NULL CHECK(price=5),result TEXT NOT NULL CHECK(length(trim(result))>0),delivery TEXT NOT NULL DEFAULT ''pending'' CHECK(delivery IN(''pending'',''sending'',''sent'',''retry'',''unknown'',''rejected'')),
