DROP TRIGGER astra_tarot31_intent_insert;
CREATE TRIGGER astra_tarot31_intent_insert BEFORE INSERT ON astra_tarot31_intents BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM astra_tarot31_receipts WHERE telegram_id=NEW.telegram_id AND generation=NEW.generation AND(request_key=NEW.request_key OR update_id=NEW.update_id))THEN RAISE(ABORT,'INTENT_REQUEST_SEEN') END;
 SELECT CASE WHEN NEW.state<>'quoted' OR NEW.lease IS NOT NULL OR NEW.lease_until<>0 OR NEW.created_at<>unixepoch() OR NOT EXISTS(SELECT 1 FROM astra_users u JOIN astra_user_policy g USING(telegram_id) JOIN astra_tarot25_runtime29 r ON r.singleton=1 JOIN astra_tarot30_policy s ON s.singleton=1 JOIN astra_tarot31_policy p ON p.singleton=1 JOIN astra_tarot25_prices29 t ON t.price_version=r.price_version AND t.spread_id=NEW.spread_id WHERE u.telegram_id=NEW.telegram_id AND g.generation=NEW.generation AND r.enabled=1 AND r.migration_done=1 AND s.migration_done=1 AND s.write_enabled=1 AND p.migration_done=1 AND p.enabled=1 AND p.revision=NEW.intent_revision AND r.revision=NEW.policy_revision AND NEW.price_version=t.price_version AND NEW.price=t.price AND(t.theme='general' OR t.theme=NEW.theme))THEN RAISE(ABORT,'INTENT_GATE_OR_OWNER')END;
 SELECT CASE WHEN(SELECT count(*) FROM astra_tarot31_intents WHERE telegram_id=NEW.telegram_id AND generation=NEW.generation AND state IN('quoted','sealing','sealed') AND expires_at>unixepoch())>=(SELECT max_open FROM astra_tarot31_policy)THEN RAISE(ABORT,'INTENT_OPEN_LIMIT')END;
 SELECT CASE WHEN coalesce((SELECT used FROM astra_tarot31_burst WHERE telegram_id=NEW.telegram_id AND generation=NEW.generation AND window=unixepoch()/60),0)>=(SELECT burst_limit FROM astra_tarot31_policy)THEN RAISE(ABORT,'INTENT_BURST_LIMIT')END;
 SELECT CASE WHEN(coalesce((SELECT used_bytes+overhead_bytes FROM astra_storage251 WHERE singleton=1 AND version='storage251-v1'),9223372036854775807))+65536>(SELECT soft_cap_bytes FROM astra_tarot30_policy)THEN RAISE(ABORT,'DRAFT_STORAGE_SOFT_CAP')END;
END;
DROP TRIGGER astra_tarot30_offer_admission;
CREATE TRIGGER astra_tarot30_offer_admission BEFORE INSERT ON astra_tarot25_offers29 BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM astra_tarot25_offers29 WHERE offer_id=NEW.offer_id)THEN RAISE(IGNORE)END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM astra_tarot31_intents i JOIN astra_tarot31_policy p ON p.singleton=1 JOIN astra_tarot30_policy s ON s.singleton=1 WHERE i.offer_id=NEW.offer_id AND i.telegram_id=NEW.telegram_id AND i.generation=NEW.generation AND i.request_key=NEW.request_key AND i.update_id=NEW.update_id AND i.spread_id=NEW.spread_id AND i.theme=NEW.theme AND i.price=NEW.price AND i.policy_revision=NEW.policy_revision AND i.state='sealing' AND i.lease_until>unixepoch() AND i.expires_at>unixepoch() AND p.enabled=1 AND p.revision=i.intent_revision AND s.write_enabled=1 AND json_extract(NEW.snapshot_json,'$.created_at')=strftime('%Y-%m-%dT%H:%M:%fZ',i.created_at,'unixepoch') AND json_extract(NEW.snapshot_json,'$.question') IS(SELECT text FROM astra_tarot31_questions WHERE offer_id=i.offer_id))THEN RAISE(ABORT,'INTENT_SEAL_AUTHORITY')END;
 SELECT CASE WHEN json_type(NEW.snapshot_json,'$.question')='text' AND NOT EXISTS(SELECT 1 FROM astra_tarot31_questions q WHERE q.offer_id=NEW.offer_id AND q.text=json_extract(NEW.snapshot_json,'$.question') AND q.policy_version=json_extract(NEW.snapshot_json,'$.question_proof.policy_version') AND q.consented_at=json_extract(NEW.snapshot_json,'$.question_proof.consented_at') AND q.consent_update=json_extract(NEW.snapshot_json,'$.question_proof.consent_update') AND q.consent_message=json_extract(NEW.snapshot_json,'$.question_proof.consent_message'))THEN RAISE(ABORT,'QUESTION_PROOF_MISMATCH')END;
 SELECT CASE WHEN NEW.engine_version<>'tarot25-v2' OR json_extract(NEW.snapshot_json,'$.text_version') IS NOT 'rws78-interpretation-v2' THEN RAISE(ABORT,'INTENT_TEXT_VERSION')END;
 SELECT CASE WHEN(coalesce((SELECT used_bytes+overhead_bytes FROM astra_storage251 WHERE singleton=1 AND version='storage251-v1'),9223372036854775807))+2*(length(CAST(NEW.snapshot_json AS BLOB))+length(CAST(NEW.result AS BLOB)))+65536>(SELECT soft_cap_bytes FROM astra_tarot30_policy)THEN RAISE(ABORT,'DRAFT_STORAGE_SOFT_CAP')END;
END;
DROP TRIGGER astra_tarot30_request_guard;
CREATE TRIGGER astra_tarot30_request_guard BEFORE INSERT ON astra_tarot30_requests WHEN(SELECT migration_done FROM astra_tarot30_policy)=1 BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM astra_tarot30_requests WHERE telegram_id=NEW.telegram_id AND generation=NEW.generation AND(request_key=NEW.request_key OR update_id=NEW.update_id)) THEN CASE WHEN EXISTS(SELECT 1 FROM astra_tarot30_requests WHERE telegram_id=NEW.telegram_id AND generation=NEW.generation AND request_key=NEW.request_key AND update_id=NEW.update_id AND offer_id=NEW.offer_id AND spread_id=NEW.spread_id AND theme=NEW.theme) THEN RAISE(IGNORE) ELSE RAISE(ABORT,'DRAFT_REQUEST_SEEN') END END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM astra_tarot25_offers29 o JOIN astra_users u ON u.telegram_id=o.telegram_id JOIN astra_user_policy p ON p.telegram_id=u.telegram_id WHERE o.offer_id=NEW.offer_id AND o.telegram_id=NEW.telegram_id AND o.generation=NEW.generation AND p.generation=o.generation AND o.spread_id=NEW.spread_id AND o.theme=NEW.theme AND o.status='open' AND o.expires_at>unixepoch() AND o.policy_revision=(SELECT revision FROM astra_tarot25_runtime29 WHERE singleton=1) AND o.price_version=(SELECT price_version FROM astra_tarot25_runtime29 WHERE singleton=1) AND NEW.created_at=unixepoch() AND EXISTS(SELECT 1 FROM astra_tarot30_policy WHERE migration_done=1 AND write_enabled=1) AND NOT EXISTS(SELECT 1 FROM astra_tarot25_purchases29 WHERE offer_id=o.offer_id)) THEN RAISE(ABORT,'DRAFT_REQUEST_AUTHORITY') END;
 SELECT CASE WHEN NEW.original=1 AND NOT EXISTS(SELECT 1 FROM astra_tarot25_offers29 WHERE offer_id=NEW.offer_id AND request_key=NEW.request_key AND update_id=NEW.update_id) THEN RAISE(ABORT,'DRAFT_REQUEST_ORIGINAL') END;
 SELECT CASE WHEN (coalesce((SELECT used_bytes+overhead_bytes FROM astra_storage251 WHERE singleton=1 AND version='storage251-v1'),9223372036854775807))+8192>(SELECT soft_cap_bytes FROM astra_tarot30_policy) THEN RAISE(ABORT,'DRAFT_STORAGE_SOFT_CAP') END;
END;
